custom_css:
/*★四重奏@夜行性鲨鱼 二改版❤️
禁商用禁二传禁二改（也给我吃一口的话可以二改₍ᐢ.ˬ.ᐢ₎），无言退群的请不要用我的美化……
气泡宽度默认360px，觉得太宽或太窄的可以自己调
标注🎶的是自定义文字区域*/

/*==== 气泡====*/
body.bubblechat .mes,body.bubblechat .mes[is_user="true"],.mes{padding:240px 15px 30px!important;border-radius:0px!important;border:1px solid #3a0f0f!important;box-shadow:8px 8px 20px rgba(0,0,0,.8),inset 0 0 0 1px rgba(255,50,50,.05)!important;max-width:360px!important;margin:40px auto 20px!important;position:relative;background-color:#1c0505!important;background-image:linear-gradient(180deg,#2b0a0a 0,#0a0000 100%)!important;box-sizing:border-box!important;overflow:visible!important}.mes_block{width:100%!important;max-width:100%!important;padding:0!important;margin:0!important}
.mes_text{padding:0!important;margin:0!important;text-align:justify!important;text-justify:inter-ideograph!important;color:#e0e0e0!important;line-height:1.9!important;letter-spacing:0.05em!important;font-weight:400!important;text-rendering:optimizeLegibility!important}

/*UI排版*/
*{border-radius:0!important}.drawer-content .range-block,.inline-drawer-header h4,.standoutHeader,h4,h4[data-i18n]{border:none!important;background:0 0!important;box-shadow:none!important;color:#888888!important;text-shadow:none!important;border-radius:0!important;margin-bottom:5px!important;border-bottom:1px dashed #4a0f0f!important;padding-bottom:5px!important}

/*扩展列表修补*/
.inline-drawer-toggle,.list-group-item,.drawer-content .list-group-item,#extensions_menu .inline-drawer-toggle{background:#0a0202!important;background-image:none!important;border:1px solid #220505!important;color:#aaaaaa!important;box-shadow:none!important;text-shadow:none!important;border-radius:0!important;margin-bottom:6px!important;transition:all .3s ease}.inline-drawer-toggle:hover,.list-group-item:hover{background:#140303!important;color:#eeeeee!important;border-color:#4a0f0f!important}.inline-drawer-toggle i,.inline-drawer-toggle .fa-chevron-down,.inline-drawer-toggle .fa-chevron-right,.inline-drawer-icon{color:#884444!important;text-shadow:none!important}

/*控件扁平化 */
.text_pole,textarea,select,.menu_button,.character_select,.group_select,input[type="text"],input[type="number"]{background-color:#050000!important;border:1px solid #2a0505!important;color:#cccccc!important;border-radius:0!important;box-shadow:none!important;transition:all .3s ease}.menu_button{background-color:#0a0202!important}.text_pole:focus,textarea:focus,select:focus{border-color:#aa3333!important;background-color:#0a0202!important;box-shadow:0 0 15px rgba(200,50,50,.15)!important;outline:0!important}.menu_button:hover{background-color:#1a0505!important;color:#fff!important;border-color:#661111!important}#completion_prompt_manager_list{background-color:transparent!important;border:none!important}#completion_prompt_manager_list .completion_prompt_manager_prompt_name.text_muted,#completion_prompt_manager_list .completion_prompt_manager_prompt_name *,#completion_prompt_manager_list .text_muted,.completion_prompt_manager_prompt_name{color:#888888!important;opacity:1!important;-webkit-text-fill-color:#888888!important;text-shadow:none!important}

/*滑块微调 */
input[type="range"]{-webkit-appearance:none!important;appearance:none!important;background:linear-gradient(#4a0f0f,#4a0f0f)center/100% 1px no-repeat!important;height:28px!important;border:0!important;box-shadow:none!important;outline:0!important;filter:grayscale(1)!important;mix-blend-mode:normal!important;opacity:1!important;cursor:pointer;overflow:visible!important}input[type="range"]::-webkit-slider-thumb{-webkit-appearance:none!important;width:59px!important;height:48px!important;background:url('https://iili.io/BP7tSvp.png')center/contain no-repeat!important;border:0!important;border-radius:0!important;filter:drop-shadow(1px 1px 2px rgba(0,0,0,.8)) grayscale(1) brightness(1.2)!important}input[type="range"]::-moz-range-thumb{width:38px!important;height:26px!important;background:url('https://files.catbox.moe/aeisa5.png')center/contain no-repeat!important;border:0!important;border-radius:0!important;filter:drop-shadow(1px 1px 2px rgba(0,0,0,.8)) grayscale(1) brightness(1.2)!important}

/*复选框 */
input[type="checkbox"]{border-radius:0!important;-webkit-appearance:none;appearance:none;background:0 0!important;border:1px solid #4a0f0f!important;width:16px;height:16px;position:relative;vertical-align:middle;cursor:pointer;outline:0!important}input[type="checkbox"]:checked{border-color:#ff4444!important;background:0 0!important}input[type="checkbox"]::before{content:none!important}input[type="checkbox"]:checked::after{content:''!important;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%)!important;width:28px;height:28px;background:url('https://iili.io/BPldmIs.png')center/cover no-repeat!important;filter:grayscale(1) brightness(1.5)!important}::-webkit-scrollbar{display:none}

/*顶栏图标*/
#top-bar{margin:0 auto;left:0;right:0;display:inline-block;height:24px;position:absolute;box-shadow:none;opacity:0;z-index:3005}.drawer-icon{transform:scale(.55);color:#fff}

/*输入栏 */
#send_form{display:flex;flex-wrap:wrap;align-items:center;width:94%!important;max-width:800px;margin:10px auto!important;background:#0a0202!important;border:1px solid #2a0505!important;border-radius:0!important;box-shadow:0 10px 30px rgba(30,0,0,.5)!important}#nonQRFormItems{padding:4px 12px!important;position:relative;display:flex;flex-direction:row;column-gap:5px;order:25;width:100%;min-height:40px!important;align-items:center;overflow:hidden;background-color:#0a0202!important;border:none!important;box-shadow:none!important;z-index:50}.qr--buttons{opacity:0;visibility:hidden;max-height:0;margin:0!important;padding:0!important;transform:translateY(15px);transition:all .3s cubic-bezier(.2,1,.3,1);overflow:hidden}#send_form:focus-within .qr--buttons{opacity:1;visibility:visible;max-height:300px;margin-bottom:8px!important;transform:translateY(0);pointer-events:auto}#rightSendForm>div:not(.mes_stop),#leftSendForm>div{transform:scale(.6)!important;color:#884444}

/*输入渐变*/
#send_textarea{background:0 0!important;border:0!important;box-shadow:none!important;color:#dddddd!important}#send_textarea::placeholder,#send_textarea::-webkit-input-placeholder{color:transparent!important;opacity:0!important;-webkit-text-fill-color:transparent!important}#nonQRFormItems:has(#send_textarea:placeholder-shown)::before{content:"「Do You Love Me？」"!important;/*🎶*/position:absolute!important;top:50%!important;left:50%!important;transform:translate(-50%,-50%)!important;font-style:italic!important;font-size:14px!important;pointer-events:none!important;z-index:10!important;white-space:nowrap!important;color:#884444!important;letter-spacing:1px!important}#chat{-webkit-mask-image:linear-gradient(to bottom,transparent 0,#000 25px,#000 calc(100% - 35px),transparent 100%);mask-image:linear-gradient(to bottom,transparent 0,#000 25px,#000 calc(100% - 35px),transparent 100%)}

/*思维链 */
.mes_reasoning_details{width:100%!important;margin:15px 0!important;border:0!important;background:0 0!important;overflow:visible!important}.mes_reasoning_header,.mes_reasoning_summary,.mes_reasoning_header_text{background:#0a0202!important;background-image:none!important;box-shadow:none!important;border-radius:0!important}.mes_reasoning_summary{width:100%!important;box-sizing:border-box!important;border:1px solid #2a0505!important;border-left:4px solid #8b0000!important;padding:8px 15px!important;color:#aaaaaa!important;position:relative!important;display:flex!important;align-items:center!important;min-height:32px!important;cursor:pointer!important;box-shadow:3px 3px 0 rgba(30,0,0,.8)!important;justify-content:flex-start!important;font-size:12px!important;letter-spacing:1px!important}.mes_reasoning_summary::after{content:''!important;position:absolute;left:8px;top:50%;transform:translateY(-50%)!important;width:20px;height:14px;background:url('https://iili.io/BP1m09n.png')center/contain no-repeat!important;filter:grayscale(1) brightness(1.5)!important}.mes_reasoning{width:100%!important;box-sizing:border-box!important;background:#050000!important;border:1px dashed #4a0f0f!important;border-top:0!important;color:#997777!important;font-size:.85em!important;line-height:1.7!important;padding:15px!important;margin:0!important}.mes_reasoning_header_icon,.mes_reasoning_details summary::marker{position:absolute!important;right:10px!important;top:50%;transform:translateY(-50%)!important;color:#884444!important}

/*正文修饰 */
.mes_text strong{position:relative!important;color:#ffffff!important;font-weight:700!important;letter-spacing:0.15em!important;text-shadow:1.5px 1.5px 0px rgba(255,50,50,0.2),-1px -1px 0px rgba(0,0,0,0.8)!important;padding:0 4px!important;border-bottom:1px solid rgba(255,50,50,0.4)!important;margin:0 2px!important}
.mes_text em{position:relative!important;padding-left:18px!important;font-style:italic!important;color:#aaaaaa!important;display:inline-block!important;letter-spacing:1px!important}.mes_text em::before{content:''!important;position:absolute!important;left:0;top:50%;transform:translateY(-50%)!important;width:20px;height:15px;background:url('https://iili.io/BP1m09n.png')center/contain no-repeat!important;filter:grayscale(1) brightness(1.5) drop-shadow(1px 1px 0 rgba(0,0,0,.8))!important}
pre code,pre span{background:0 0!important;color:inherit!important;text-shadow:none!important}

/*代码块 */
pre{background:#0a0202!important;color:#ccc!important;border:1px solid #3a0f0f!important;box-shadow:5px 5px 0 #1a0505,10px 10px 0 #0a0000!important;margin:30px 0!important;padding:40px 15px 15px!important;position:relative!important}
pre::before{content:'脏腑、后颈、骨骼，我就是这些东西。'!important;/*🎶*/position:absolute;top:-1px;left:-1px;background:#8b0000!important;color:#fff!important;padding:6px 15px 6px 35px!important;letter-spacing:.2em!important;font-weight:900!important;font-size:.7em!important;box-shadow:2px 2px 0 rgba(0,0,0,.5)!important}
pre::after{content:''!important;position:absolute;top:6px;left:10px;width:20px;height:15px;background:url('https://iili.io/BP0uEHg.png')center/contain no-repeat!important;filter:brightness(0)!important;z-index:10}

/*对话引用样式 */
q{color:#e0e0e0!important;background:0 0!important;border:0!important;padding:0 15px!important;font-style:normal!important;font-weight:700!important;position:relative;display:inline-block;letter-spacing:1px}q::before{content:'「'!important;position:absolute;left:-5px;top:-5px;font-size:1.5em;color:rgba(255,50,50,.3)}q::after{content:'」'!important;position:absolute;right:-5px;bottom:-5px;font-size:1.5em;color:rgba(255,50,50,.3)}
:not(pre)>code{background:#1a0505!important;color:#fff!important;padding:2px 10px!important;border:1px solid #3a0f0f!important;box-shadow:2px 2px 0 #2a0a0a,4px 4px 0 #1a0505!important;margin:0 4px!important;letter-spacing:.15em!important;display:inline-block!important;line-height:1.4!important;text-shadow:0 0 5px rgba(255,50,50,.2)!important;vertical-align:middle}

/*引用块 */
blockquote{margin:30px 0!important;padding:20px!important;border:1px solid #3a0f0f!important;background:#0a0202!important;box-shadow:4px 4px 0 #1a0505,8px 8px 0 #0a0000!important;color:#aaa!important;position:relative!important;display:block!important;font-style:italic!important;letter-spacing:.05em!important}
blockquote::after{content:'我将在你心里占据一席之地。'!important;/*🎶*/position:absolute;top:-11px;right:15px;background:#4a0f0f!important;color:#fff!important;padding:2px 8px!important;font-size:.7em!important;font-weight:900!important;letter-spacing:.2em!important;box-shadow:2px 2px 0 #000!important}

/*====== 封面画报排版+gif动效 ======*/
/*gif如需启用在url下方0.0调成0.2*/
.mesAvatarWrapper{width:calc(100% - 20px)!important;height:220px!important;position:absolute!important;left:10px!important;top:10px!important;z-index:5!important;background:#000 url('https://iili.io/BPuLsjf.gif')center/cover no-repeat!important;overflow:hidden!important;border:1px solid #1a1a1a!important;box-shadow:inset 0 0 50px rgba(0,0,0,.9)!important}.mesAvatarWrapper .avatar{width:70%!important;height:100%!important;position:absolute!important;right:0!important;top:0!important;-webkit-mask-image:linear-gradient(to right,transparent 0,black 50%,black 100%)!important;mask-image:linear-gradient(to right,transparent 0,black 50%,black 100%)!important}.mesAvatarWrapper .avatar img{width:100%!important;height:100%!important;object-fit:cover!important;filter:brightness(0.95)!important}.mesAvatarWrapper::before{content:"SILENT ARCHIVE / FALLING SNOW..."!important;/*🎶想改也可以，但这里，没什么改的必要*/position:absolute!important;left:10px!important;top:50%!important;transform:rotate(-90deg) translateY(-50%)!important;transform-origin:left center!important;font-size:8px!important;color:rgba(255,255,255,.6)!important;letter-spacing:3px!important;white-space:nowrap!important;z-index:10;text-shadow:0 0 4px rgba(255,255,255,.4)!important}
.mesAvatarWrapper .avatar::after{content:""!important;position:absolute!important;right:105px!important;top:130px!important;width:65px!important;height:65px!important;z-index:10!important;background:url('https://iili.io/BP7tSvp.png') center/contain no-repeat!important;filter:drop-shadow(2px 2px 2px rgba(0,0,0,0.9)) drop-shadow(0 0 10px rgba(255,255,255,0.15))!important;border:none!important;pointer-events:none!important}
.mesAvatarWrapper::after{content:""!important;position:absolute!important;left:0!important;top:0!important;width:100%!important;height:100%!important;z-index:15!important;background:url('https://iili.io/BryqDf2.gif')   center/cover no-repeat!important;opacity:0.0!important;pointer-events:none!important}
.mes .name_text{font-size:1.8em!important;font-weight:700!important;position:absolute!important;left:25px!important;top:140px!important;text-align:left!important;color:#ff0000!important;letter-spacing:2px!important;z-index:20;text-shadow:2px 2px 4px rgba(0,0,0,.9),-1px -1px 0 rgba(255,255,255,.2)!important;width:calc(100% - 60px)!important;word-wrap:break-word!important}

.mes .name_text::after{
  content:"你很乖，乖乖的回到我肚子裡。"!important;/*🎶*/
  display:block!important;
  font-size:12px!important;
  font-weight:400!important;
  letter-spacing:0.5px!important;
  margin-top:8px!important;

  color:transparent!important;
  background:linear-gradient(to right, #cccccc 0%, #cccccc 78%, red 78%)!important;
  -webkit-background-clip:text!important;
  background-clip:text!important;
  -webkit-text-fill-color:transparent!important;
  text-transform:none!important;

  /* text-shadow:0 0 5px #000!important; */
  font-style:italic!important;
  white-space:normal!important;
  line-height:1.3!important;
}

.mes .mes_timer,.mes .mesIDDisplay,.mes .tokenCounterDisplay{background:transparent!important;color:#666666!important;top:200px!important;font-size:10px!important}.mes .timestamp{top:240px!important;font-style:italic;border-top:1px solid #1a1a1a;padding-top:8px;width:80%;color:#555555!important}

/*弹窗*/
#toast-container>.toast{color:#cccccc!important;background:rgba(10,0,0,.95)!important;backdrop-filter:blur(5px)!important;border:1px solid #3a0f0f!important;outline:0!important;box-shadow:0 10px 30px rgba(30,0,0,.6)!important;padding:15px 5px 15px 45px!important;border-radius:0px!important}#toast-container>.toast::before{content:''!important;position:absolute!important;left:18px!important;top:50%!important;transform:translateY(-50%)!important;width:24px!important;height:24px!important;background:url('https://iili.io/BPclpVf.png')center/contain no-repeat!important;filter:grayscale(1) brightness(1.5)!important}#toast-container>.toast-success::before{filter:grayscale(1) brightness(2)!important}#toast-container>.toast-info::before{filter:grayscale(1) brightness(1.2)!important}#toast-container>.toast-error::before,#toast-container>.toast-warning::before{background:url('https://iili.io/BPclpVf.png')center/contain no-repeat!important;left:14px!important}#toast-container>.toast-error::before{filter:grayscale(1)!important}#toast-container>.toast-warning::before{filter:grayscale(1) brightness(0.8)!important}
